with ins as (insert into public.artist_sound_tags (artist_slug,tag,source_url) select x.s,x.tag,x.u from json_to_recordset('[{"s":"ak-sports","tag":"new-world-rave under the techno umbrella","u":"https://brokemagazine.co.uk/ak-sports-b2b-broke-magazine"},{"s":"ak-sports","tag":"hard, fast, fun techno sets and productions","u":"https://grayarea.co/magazine/ones-to-watch-ak-sports"},{"s":"audio-units","tag":"heart-pounding techno with some dub features","u":"https://dirty-epic.com/2023/04/10/audio-units-the-gateway-experience-anaoh-records-april-3rd-2023/"},{"s":"audio-units","tag":"4/4 rhythms with glitchy digital bleeps and swirling textures","u":"https://mixmag.asia/read/mama-snake-audio-units-and-kollision-in-the-lab-mumbai-local"},{"s":"kaleekarma","tag":"Shifting soundscapes and states of mind","u":"https://mixmag.net/read/kaleekarma-in-the-lab-goa-dj-lab-dj-lab"},{"s":"long-distances","tag":"Indie band at the intersections of post-punk, shoegaze, dreampop and synthpop","u":"https://www.platform-mag.com/music/how-the-mighty-will-fall.html"},{"s":"lush-lata","tag":"Achingly cool, unbothered, and fluid, wrapped in a detached mystique","u":"https://refugeworldwide.com/artists/lush-lata"},{"s":"sijya","tag":"textural abstractions of her inner monologue","u":"https://www.cafeoto.co.uk/artists/sijya"},{"s":"sijya","tag":"a lyrical concoction of art-pop, downtempo and ambient","u":"https://www.thewildcity.com/artists/19290-Sijya"},{"s":"suchi","tag":"wafty house and nostalgic rave records","u":"https://mixmag.net/feature/top-dance-music-rap-artists-watch-check-out-2022"}]'::json) as x(s text,tag text,u text) join public.artists a on a.slug=x.s on conflict (artist_slug,tag) do nothing returning 1) select count(*) from ins;